from utils import *
from collections import Counter
loadj=lambda f:json.loads((ROOT/f).read_text(encoding='utf-8'))
manifest=loadj('研究清单.json');M=loadj('measurement_results.json');DC=loadj('daily_conditional_coefficients.json');FC=loadj('factor_coefficients.json');MC=loadj('macro_coefficients.json');FU=loadj('fund_coefficients.json');HR=loadj('hourly_lead_results.json');IA=loadj('inference_audit.json');sources={x['id']:x for x in loadj('literature_sources.json')}
rows={}
def add(i,finding,counter,limit,file,data,kind='实证',strength='有限或未确立'):
 r=dict(manifest[i-1]);r.update(status='completed',kind=kind,evidence_strength=strength,finding=finding,countercheck=counter,limitation=limit,evidence_file=file,evidence=data);rows[i]=r
def selected(file,**filters):
 a=loadj(file);return [x for x in a if all(x.get(k)==v for k,v in filters.items())]
def test(i,file,filters,finding,counter,limit='历史样本外检验不是前瞻盲测；不显著不能证明效应为零。'):
 data=selected(file,**filters);assert data
 add(i,finding,counter,limit,file,data)
def mc(i,factors,statement):
 data={k:{'n':v['n'],'first':v['first'],'last':v['last'],'coefficients':[a for a in v['coefficients'] if a['factor'] in factors]} for k,v in MC.items() if k.endswith('_extended')}
 add(i,statement,'采用同一样本、同一组宏观控制，分别估计黄金、白银和比值；检查区块区间。','同期条件关联不能解释为政策冲击的因果效应，也不能直接当提前信号。','macro_coefficients.json',data)
def lit(i,ids,finding,counter,limit):
 add(i,finding,counter,limit,'literature_sources.json',[sources[x] for x in ids],kind='文献及识别审查',strength='有来源支持，适用范围受限')
add(1,'Δln(金银比)=黄金对数收益−白银对数收益；比值升高只确定黄金相对白银更强。','比值均升 2% 的对数幅度，黄金可以涨 1%，也可以跌 1%。','这是恒等式；不规定经济冲击、未来收益或套利利润。','measurement_results.json',M['identity'],'数学','确定')
add(2,'相同 5 点变化，从 40 起步是 12.5%，从 100 起步是 5%；点数速度不能跨时期直接比较。','同时核对普通百分比与对数变化；对数速度适合相加分解。','标准化异常仍依赖历史窗口，不能自动成为情绪量表。','measurement_results.json',M['identity']['equal_point_change'],'数学','确定')
add(3,'同一时刻共同换算汇率 k 时，(kG)/(kS)=G/S；美元的经济冲击仍可因金银敏感度不同而改变比值。','数值换算不变性与多因子美元差异系数分开检查。','抵消的是计价换算，不是金银对美元冲击的全部反应。','macro_coefficients.json',MC['qret20_extended'],'数学与实证','恒等部分确定；经济部分有条件')
add(4,'黄金收益、白银收益和比值收益三列只有两个独立方向；将三者同时无约束回归会产生精确共线性。','直接检查价格序列生成的设计矩阵秩，并与收益恒等式对照。','非线性特征、不同滞后和不同信息源可以包含新信息，不能据此说所有比值模型都无用。','measurement_results.json',M['identity'],'数学','确定')
add(5,'控制同一个黄金收益和常数后，比值收益残差恰等于白银收益残差的负值。','两次独立投影的残差相加误差接近浮点精度。','残差异常仍可能有预测价值；但它不是不含金银信息的独立第三种资产。','measurement_results.json',{'max_error':M['residual_equivalence_max_error']},'数学','确定')
add(6,'比值风险由金银各自方差和二者协方差共同构成，不能把变快全部归因于黄金风险。','分期核对 Var(g−s)=Var(g)+Var(s)−2Cov(g,s)。','历史协方差会变；此恒等式不识别协方差变化的原因。','measurement_results.json',M['variance_decomposition'],'数学与实证','恒等部分确定')
add(7,'一比一名义金额价差不是最小方差黄金对冲；本样本滚动白银对冲系数中位数约 0.47。','以前一期估计的系数计算后一期价差风险，与固定一比一比较。','这是历史风险比较，未计融资、保证金、交易成本，也不保证压力期对冲效果。','measurement_results.json',M['hedge'],'实证','样本支持')
add(8,'期货每份未平仓合约同时对应一个多头与空头；某类别净多增加不代表全市场凭空增加净多。','2,042 条报告中，多头和空头分别加总到未平仓量。','价格由边际成交和流动性形成，会计平衡不意味着价格不受交易影响。','measurement_results.json',M['accounting'],'会计','确定')
add(9,'净多占未平仓量比例与净多合约变化会因分母变化出现相反方向。','1,020 个变化周期中，黄金 95 次、白银 68 次方向不一致；分子分母分解误差接近零。','方向不一致不等于数据错误，也不能据比例变化推断成交净流出金额。','measurement_results.json',M['denominator'],'会计与实证','确定且样本验证')
add(10,'预测误差下降不保证方向正确，更不保证扣费后的交易收益。','真实收益 +0.1%；预测由 −1% 改为 −0.1% 时平方误差显著下降，但据预测做空仍亏损。','本研究评价统计预测，未构建或宣称盈利交易策略。','measurement_results.json',{'actual':.001,'old':-.01,'new':-.001,'old_mse':.011**2,'new_mse':.002**2},'数学反例','确定')
add(11,'ETF 每份代表的金银数量不同，ETF 价格比不能套用现货 60、80 等水平。','将 ETF 月均价格比与世界银行美元/盎司比值匹配，检查比例及漂移。','费用、每份含量、报价时点和跟踪误差令长期比例也不是严格常数。','measurement_results.json',M['measurement'],'测量','样本支持')
add(12,'月均黄金价除以月均白银价不等于每日金银比的月均值。','在同一个 ETF 日线样本同时聚合两种口径，保留最大与典型差异。','本次测量差异不是现货月均数据质量错误；长期结果需遵守原数据定义。','measurement_results.json',M['measurement'],'测量','确定且样本验证')
add(13,'ETF 与连续期货的相对变化高度相关但不相同，不能将差异直接称为市场先后。','同时比较共同日和周聚合相关；前序轮次也换发行人重跑模型。','合约切换、结算时点、基金费用可能造成偏差；连续期货并非无成本可持有组合。','measurement_results.json',M['measurement'],'测量','样本支持')
add(14,'只把白银报价时钟错移一段，就能把很强的同期联系伪装成黄金领先。','负面对照保留原价格，只移动时间标签；真实同步相关与伪造领先相关均约 0.81。','此为故意制造的时间错误示例，绝不是观测到真实领先 0.81。','hourly_lead_results.json',HR['descriptions'],'测量反例','确定且样本验证')
add(15,'开收盘收益平方会漏掉日内先涨后跌；约三成完整日的终点平方小于分时平方和的四分之一。','逐日比较开收盘平方与 7 段收益平方和。','小时平方和仍遗漏小时内部路径，也不等于逐笔真实积分方差。','measurement_results.json',M['hourly_measurement']['GLD_SLV']['risk'],'测量','样本支持')
add(16,'此 ETF 完整日样本中，隔夜平方项占粗粒度总平方风险约 65%，忽略隔夜会改变研究对象。','分别计算金银总和占比与逐日中位数，不将隔夜净变动当连续隔夜 RV。','缺失极端日、ETF 交易时段及隔夜净额口径限制该比例向国际全天市场外推。','measurement_results.json',M['hourly_measurement']['GLD_SLV']['risk'],'测量','局部样本支持')
add(17,'开盘、盘中、尾盘风险必须按交易分钟数比较；最后一段只有 30 分钟。','逐时段统计每分钟收益平方，并在不同发行人的样本重复。','每分钟平方只是粗粒度风险密度，不是可直接交易的波动率。','measurement_results.json',{p:x['by_slot'] for p,x in M['hourly_measurement'].items()},'测量','局部样本支持')
add(18,'501 个交易日期只有 493 个完整日，2026-01-30 与 02-02 的缺失尤其限制压力检验。','日线收盘交叉核对；不完整日 RV 和碰到缺失日的未来窗口保持缺失，不填成低风险。','2026-01-30 日线金银跌幅约 10.27% / 28.54%，小时样本遗漏重大极端事件，不能声称覆盖全部危机。','measurement_results.json',M['hourly_measurement']['GLD_SLV']['excluded_days_daily_returns'],'数据审计','明确限制')
add(19,'同一段美元、利率变化解释同期金价，和昨天数据预测明天价格属于不同问题。','宏观 *0 回归与至少滞后一日的预测回归分开；比较二者符号和区间。','昨日数据在历史库中也可能修订；未取得全部初始版本。','macro_coefficients.json',{'contemporaneous':MC['gret20_extended'],'predictive':FC['future_return20']},'信息时间','确定的识别区分')
add(20,'COT 截至日期与公众可用日期不一样；本批次有效特征使用距截至日 10—17 天的保守观测。','核对年龄分布，且停发窗口和过旧观测不可用。','保守日期不是完整实际发布档案；本批次广义样本含少量非周二截至日，年龄上限不同于前序模型筛选后的 16 天。','measurement_results.json',M['timing'],'信息时间','明确限制')
add(21,'长期比值中心跨阶段明显变化，固定数字不具有已验证的跨年代稳定性。','预定四个时间段的比值中位数约 39.71、70.72、62.27、82.48。','分组差异不是正式证明所有均值回归模型无效；均衡本身可以时变。','measurement_results.json',M['decade_ratio'],'实证','较强描述证据')
add(22,'对数金价对对数银价的分期斜率并不总接近 1；样本斜率约 0.98、0.55、0.67、0.97。','保留每段区块区间，而不是只报告全样本一条回归线。','非平稳价格水平回归可能伪回归；本项没有将普通 OLS 区间当成协整检验。','measurement_results.json',M['long_coefficients'],'实证','描述性，非协整确证')
