add(49,'短期相对反转存在部分样本内迹象，但加入其他条件后不构成稳健的反向投资规则。','同时检查相对收益前推误差、正负冲击和完整多因子系数。','样本内比值速度的负系数不能推出做多黄金；相对回归可由白银上涨完成。','daily_conditional_coefficients.json',{'conditional':DC['relative'],'full':FC['future_ratio20']})
