test(51,'hourly_risk_results.json',{'variant':'main','period':'all','metric':'MSE'},'小时代理中，1 日异常压力出现小幅点改善，5 日未保持；未确立稳定风险预测能力。','三特征、两个期限、两种基准全部记录并校正多重检验。','1 日仅 156 个、5 日仅 140 个信号；缺失重大极端日，且不是原论文压力指标的复制。')
test(52,'hourly_risk_results.json',{'variant':'main','period':'all','baseline':'cross','metric':'MSE'},'加入白银自身分时风险后，原始幅度与标准幅度的改善消失；压力代理仍有短期迹象但不稳健。','所有模型保持共同样本，避免样本范围改变造成假改善。','换基准不保证完全隔离信息来源；白银风险与比值特征相关。')
test(53,'hourly_risk_results.json',{'variant':'with_overnight','period':'all','metric':'MSE'},'纳入隔夜平方项后结果需要单独解释，不能把美股时段内结论直接当全天金价风险结论。','沿用同一特征，只改变风险目标，保留全部结果。','隔夜净变化平方并不是逐小时国际夜盘实现方差。')
test(54,'hourly_risk_results.json',{'variant':'gap_one_day','period':'all','metric':'MSE'},'留出完整交易日的检验没有给出普遍、稳定的比值压力优势。','先前日数据和目标间留空档，减少紧邻波动持续性的误读。','空档同时可能丢失真实但很短的作用，不能据此排除分钟级机制。')
test(55,'hourly_risk_results.json',{'variant':'other_issuer','period':'all','metric':'MSE'},'换用 IAU/SIVR 后仍未建立跨期限和基准一致的异常比值优势。','独立重建报价、分时收益、目标与所有候选特征。','不同 ETF 共同经历同一市场，不能当成独立经济实验；缺失日期也相同。')
add(56,'白银过去一两段收益加入黄金模型，黄金后续时段收益误差约增加 0.115%；未形成领先证据。','更换 ETF 后约增 0.124%；按日评价而非把每根时段都当独立样本。','小时频率会漏掉秒或分钟内的真实传播，也只覆盖纽约 ETF 时段。','hourly_lead_results.json',[x for x in HR['main'] if x['metal']=='g' and x['kind']=='return' and x['period']=='all'])
add(57,'黄金滞后收益对后续白银收益有约 0.34% 的微小点改善，未通过不确定性与多重检验。','另一对 ETF 的改善约 0.26%，保留两个年份分解。','方向上的微小统计改善不等于有净收益或识别了资金主导者。','hourly_lead_results.json',[x for x in HR['main'] if x['metal']=='s' and x['kind']=='return' and x['period']=='all'])
add(58,'黄金过去的平方收益对白银下一时段风险有约 5.4% 点改善，强于方向改善，但区间和校正不足以确证。','反向白银→黄金并未改善；另一对 ETF 点改善约 5.0%。','平方收益目标很噪，极端事件遗漏和短样本使“波动传递”只能保留为待验证方向。','hourly_lead_results.json',[x for x in HR['main'] if x['kind']=='variance' and x['period']=='all'])
add(59,'时段切分显示先后表现有时间依赖，不能把全日平均当每小时都有效。','上午、下午分别按日汇总评分，两个方向和两个目标全部保留。','时段子样本也是探索性多次比较，未从中选择交易窗口。','hourly_lead_results.json',[x for x in HR['sections'] if x['section'] in ['morning','afternoon']])
add(60,'极端误差日敏感性揭示领先幅度的不稳定，不能仅凭全样本一点改善断言主导顺序。','删除每个基准模型最差 5 个交易日再比较；与保留极端日结果并列。','这个剔除仅用于解释误差来源，不能作为实时筛选规则。','hourly_lead_results.json',[x for x in HR['sections'] if x['section']=='exclude_top5_error_days'])
add(61,'最后半小时必须区别对待；评分换为每分钟方差后，依然需保留区间与不确定性。','模型包含时段控制；另把实际与预测平方收益除以分钟数后按日重新评分。','按长度转换后的误差不是新的独立数据，不能另算一次独立发现。','inference_audit.json',IA['duration_score_audit'])
