add(63,'大幅同动更多发生于同一采样时段，支持先检查共同冲击，而非先假定一方提前。','GLD/SLV 中同段双异常 85 次，黄金异常后下一段白银异常 36 次；尺度只用过去同一时段。','事件计数机会数、尾盘无下一段等不同；不能把 85/36 当正式相对概率或因果统计。','hourly_lead_results.json',HR['descriptions'],'实证','描述性支持')
add(64,'2025 与 2026 的表现不能视作稳定迁移验证；风险预测中的 2025 可评价区间尤其短。','全部候选按年份展开，不只报告最好年份。','小时数据 2026 漏掉重大暴跌日；两个年份也不足以覆盖长期不同市场状态。','hourly_risk_results.json',[x for x in loadj('hourly_risk_results.json') if x['variant']=='main' and x['period']!='all' and x['metric']=='MSE'])
