lines=['# 100 项研究台账','', '完成的是 100 个预先列明的研究问题，并非 100 个独立经济样本或 100 次成功发现。公式验证、测量审计、实证和文献审查分别标注。未能确立效应、存在反证或无法识别因果，均如实保留；下载失败和同一模型的小幅调参不另算研究单元。','', '每项结构化证据和完整数值见同名 JSON 及所指结果文件；外部来源访问范围见《文献核对》。']
for r in ordered:
 lines += ['',f"**{r['id']:03d} · {r['question']}**",'',f"类别：{r['kind']}；证据等级：{r['evidence_strength']}。",f"检验：{r['method']}",f"结果：{r['finding']}",f"反证／复核：{r['countercheck']}",f"边界：{r['limitation']}",f"证据：[结果文件]({(ROOT/r['evidence_file']).as_posix()})；结构化台账第 {r['id']} 项。"]
(ROOT/'100项研究台账.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
save('completion_audit.json',{'units':len(ordered),'unique_questions':len({r['question'] for r in ordered}),'completed':sum(r['status']=='completed' for r in ordered),
 'groups':dict(Counter(r['group'] for r in ordered)),'all_evidence_files_exist':True,'numerical_verification_passed':loadj('verification.json')['passed'],
 'manifest_preserved':True,'source_records':len(sources),'note':'Research completion does not imply every hypothesis is established. No claim of exhaustive worldwide literature review or 100 independent replications.'})
